fn enumerate(prefix: &str, alphabet: &[u8], max_len: usize) -> usize {
    let mut count = 0;
    for len in 0..=max_len {
        for mut n in 0..alphabet.len().pow(len as u32) {
            let mut input = prefix.to_owned();
            for _ in 0..len {
                input.push(alphabet[n % alphabet.len()] as char);
                n /= alphabet.len();
            }
            check(&input);
            count += 1;
        }
    }
    count
}

